const html = $json.body || '';

// 1) Detect "no offers" message
const hasNoOffers = /Keine\s+Angebote/i.test(html);

// 2) Extract candidate offer/exposé links
const hrefRegex = /href\s*=\s*"([^"]+)"/gi;
const found = new Set();
let m;

while ((m = hrefRegex.exec(html)) !== null) {
  let href = m[1];
  if (href.startsWith('/')) href = 'https://www.stwdo.de' + href;

  if (
    href.includes('stwdo.de') &&
    /expos|angebot/i.test(href) &&
    !/aktuelle-wohnangebote/i.test(href)
  ) {
    found.add(href);
  }
}

const offers = Array.from(found).sort();

// 3) Static memory (Code node v2)
const data = $getWorkflowStaticData('global');

data.prevOffers = Array.isArray(data.prevOffers) ? data.prevOffers : [];
const prevOffers = data.prevOffers;

const newOffers = offers.filter((u) => !prevOffers.includes(u));

let message = '';

// If the page does NOT say "Keine Angebote"
if (!hasNoOffers) {
  if (offers.length > 0) {
    // Notify when new offers appear (or first run)
    if (newOffers.length > 0 || prevOffers.length === 0) {
      message =
        `🏠 *StwDo dorm offers detected!*\n\n` +
        `New offers (${newOffers.length}):\n- ${newOffers.join('\n- ')}\n\n` +
        `All extracted offers (${offers.length}):\n- ${offers.join('\n- ')}\n\n` +
        `Main page: https://www.stwdo.de/wohnen/aktuelle-wohnangebote`;
    }

    // Always update stored offers when we successfully extracted them
    data.prevOffers = offers;
    data.prevFlagOffersLikely = false;
  } else {
    // Page changed (no "Keine Angebote"), but no links extracted
    // Notify once per state-change
    if (!data.prevFlagOffersLikely) {
      message =
        `🏠 *StwDo page no longer says “Keine Angebote”*\n\n` +
        `I couldn't extract offer links (markup may have changed), but it looks like offers may be available.\n\n` +
        `Check: https://www.stwdo.de/wohnen/aktuelle-wohnangebote`;
    }
    data.prevFlagOffersLikely = true;
  }
} else {
  // No offers currently
  data.prevFlagOffersLikely = false;
}

const notify = message.trim().length > 0;

return [{ json: { notify, message, hasNoOffers, offersCount: offers.length, newOffersCount: newOffers.length, offers, newOffers } }];
